import {
  getMonthNames,
  getTimeWithoutPrecision,
  getWeekdayNames,
  isCurrentMonth,
} from ".";

describe("datetime utils", () => {
  it("getMonthNames", () => {
    expect(getMonthNames()).toMatchSnapshot();
  });

  it("getWeekdayNames", () => {
    expect(getWeekdayNames()).toMatchSnapshot();
  });

  it("getTimeWithoutPrecision", () => {
    expect(getTimeWithoutPrecision(new Date("1577880732"))).toEqual(
      new Date("1577836800").getTime()
    );
  });

  it("isCurrentMonth", () => {
    expect(isCurrentMonth(2021, 5)).toBeTruthy();
  });
});
